def main():
    bad = 0
    for k, c in enumerate(CASES):
        rl = array("h", [0] * c["n"])
        rr = array("h", [0] * c["n"])
        pg.road_edges(rl, rr, array("i", c["hw"]), c["n"], c["cx"], c["dist"], array("i", c["cfg"]))
        if list(rl) != c["rl"] or list(rr) != c["rr"]:
            bad += 1
            rows = [i for i in range(c["n"]) if rl[i] != c["rl"][i] or rr[i] != c["rr"][i]]
            print("FAIL road_edges case %d: %d rows differ (first at %d)" % (k, len(rows), rows[0]))
    badr = 0
    for k, c in enumerate(ROAD):
        cv = pg.Canvas(c["w"], c["h"])
        cv.road(c["ri0"], array("h", c["tab"]), array("h", c["rl"]), array("h", c["rr"]),
                c["d05"], c["d07"], array("H", c["cols"]))
        x = 2166136261
        for px in cv._data:
            x = ((x ^ int(px)) * 16777619) & 0xFFFFFFFF
        if x != c["crc"]:
            badr += 1
            print("FAIL Canvas.road case %d: CRC %d != C %d" % (k, x, c["crc"]))
    print("road_edges %d/%d bit-exact, Canvas.road %d/%d CRC-exact"
          % (len(CASES) - bad, len(CASES), len(ROAD) - badr, len(ROAD)))
    return 1 if (bad or badr) else 0


if __name__ == "__main__":
    sys.exit(main())
